-- ═══════════════════════════ Hand-written ═══════════════════════════

-- ---------- Business-rule CHECK constraints ----------
-- The API validates all of these too; the database is the last line of defence against a
-- bug, a script or a manual fix writing an impossible state.

ALTER TABLE "users"
    ADD CONSTRAINT "users_display_name_not_blank" CHECK (length(btrim("display_name")) > 0);

ALTER TABLE "refresh_tokens"
    ADD CONSTRAINT "refresh_tokens_token_hash_hex" CHECK ("token_hash" ~ '^[0-9a-f]{64}$');
ALTER TABLE "password_reset_tokens"
    ADD CONSTRAINT "password_reset_tokens_token_hash_hex" CHECK ("token_hash" ~ '^[0-9a-f]{64}$');

ALTER TABLE "projects"
    ADD CONSTRAINT "projects_key_format" CHECK ("key" ~ '^[A-Z][A-Z0-9]{1,9}$'),
    ADD CONSTRAINT "projects_name_not_blank" CHECK (length(btrim("name")) > 0),
    ADD CONSTRAINT "projects_issue_seq_non_negative" CHECK ("issue_seq" >= 0);

ALTER TABLE "labels"
    ADD CONSTRAINT "labels_color_hex" CHECK ("color" ~ '^#[0-9a-fA-F]{6}$'),
    ADD CONSTRAINT "labels_name_not_blank" CHECK (length(btrim("name")) > 0);

ALTER TABLE "issues"
    ADD CONSTRAINT "issues_number_positive" CHECK ("number" > 0),
    ADD CONSTRAINT "issues_title_not_blank" CHECK (length(btrim("title")) > 0),
    ADD CONSTRAINT "issues_story_points_range" CHECK ("story_points" BETWEEN 0 AND 100),
    ADD CONSTRAINT "issues_version_positive" CHECK ("version" > 0),
    -- resolved_at is set exactly when the issue is in a terminal status.
    ADD CONSTRAINT "issues_resolved_at_matches_status"
        CHECK (("status" IN ('DONE', 'CANCELLED')) = ("resolved_at" IS NOT NULL));

ALTER TABLE "attachments"
    ADD CONSTRAINT "attachments_size_limit" CHECK ("size_bytes" BETWEEN 1 AND 10485760);

ALTER TABLE "sprints"
    ADD CONSTRAINT "sprints_dates_ordered" CHECK ("end_date" >= "start_date"),
    -- Lifecycle timestamps must agree with the status (PLANNED → ACTIVE → COMPLETED).
    ADD CONSTRAINT "sprints_status_timestamps" CHECK (
        ("status" = 'PLANNED'   AND "started_at" IS NULL     AND "completed_at" IS NULL) OR
        ("status" = 'ACTIVE'    AND "started_at" IS NOT NULL AND "completed_at" IS NULL) OR
        ("status" = 'COMPLETED' AND "started_at" IS NOT NULL AND "completed_at" IS NOT NULL)
    );

ALTER TABLE "sprint_issues"
    -- An outcome is recorded exactly when the issue leaves the sprint.
    ADD CONSTRAINT "sprint_issues_outcome_when_removed"
        CHECK (("removed_at" IS NULL) = ("outcome" IS NULL));

ALTER TABLE "issue_links"
    ADD CONSTRAINT "issue_links_single_target" CHECK (
        ("link_type" = 'PULL_REQUEST' AND "pull_request_id" IS NOT NULL AND "commit_id" IS NULL) OR
        ("link_type" = 'COMMIT'       AND "commit_id" IS NOT NULL       AND "pull_request_id" IS NULL)
    );

ALTER TABLE "github_pull_requests"
    ADD CONSTRAINT "github_pull_requests_head_sha_hex" CHECK ("head_sha" ~ '^[0-9a-f]{40}$');
ALTER TABLE "github_commits"
    ADD CONSTRAINT "github_commits_sha_hex" CHECK ("sha" ~ '^[0-9a-f]{40}$');
ALTER TABLE "ai_reviews"
    ADD CONSTRAINT "ai_reviews_head_sha_hex" CHECK ("head_sha" ~ '^[0-9a-f]{40}$');

ALTER TABLE "documents"
    -- Uploaded documents are their own source; every other source type points at a row.
    ADD CONSTRAINT "documents_source_id_presence"
        CHECK (("source_type" = 'UPLOAD') = ("source_id" IS NULL));

ALTER TABLE "document_chunks"
    ADD CONSTRAINT "document_chunks_chunk_index_non_negative" CHECK ("chunk_index" >= 0),
    ADD CONSTRAINT "document_chunks_token_count_positive" CHECK ("token_count" > 0);

ALTER TABLE "ai_usage"
    ADD CONSTRAINT "ai_usage_non_negative" CHECK (
        "input_tokens" >= 0 AND "output_tokens" >= 0 AND "latency_ms" >= 0 AND "cost_usd" >= 0
    );

-- ---------- Partial, expression and special-purpose indexes ----------

-- At most one ACTIVE sprint per project (FR-5.1), enforced even under concurrent "start sprint".
CREATE UNIQUE INDEX "sprints_one_active_per_project"
    ON "sprints" ("project_id") WHERE "status" = 'ACTIVE';

-- An issue is in at most one sprint at a time; history rows (removed_at set) are unlimited.
CREATE UNIQUE INDEX "sprint_issues_one_current_sprint_per_issue"
    ON "sprint_issues" ("issue_id") WHERE "removed_at" IS NULL;

-- Board/list queries only ever read non-deleted issues, so index only those.
CREATE INDEX "issues_active_by_status_idx"
    ON "issues" ("project_id", "status") WHERE "deleted_at" IS NULL;
-- Default list order (most recently updated first) with id as the cursor tie-breaker.
CREATE INDEX "issues_active_by_updated_idx"
    ON "issues" ("project_id", "updated_at" DESC, "id" DESC) WHERE "deleted_at" IS NULL;
-- Keyword search (FR-11.1).
CREATE INDEX "issues_search_vector_idx" ON "issues" USING GIN ("search_vector");

-- Unread badge: tiny index, because most notifications are read.
CREATE INDEX "notifications_unread_idx"
    ON "notifications" ("user_id") WHERE "read_at" IS NULL;

-- Outbox relay scans unpublished events oldest first; published rows drop out of the index.
CREATE INDEX "outbox_events_unpublished_idx"
    ON "outbox_events" ("id") WHERE "published_at" IS NULL;

-- Approximate nearest-neighbour search over embeddings (cosine distance). HNSW needs no
-- training step (unlike IVFFlat), so it can be built on an empty table and stays accurate as
-- rows are added. pgvector 0.8 iterative scans keep recall high when combined with the
-- project_id filter (SET hnsw.iterative_scan = relaxed_order at query time).
CREATE INDEX "document_chunks_embedding_hnsw_idx"
    ON "document_chunks" USING hnsw ("embedding" vector_cosine_ops) WITH (m = 16, ef_construction = 64);
CREATE INDEX "document_chunks_search_vector_idx" ON "document_chunks" USING GIN ("search_vector");

-- ---------- Append-only audit log (FR-13) ----------

CREATE FUNCTION "audit_logs_reject_modification"() RETURNS trigger
    LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'audit_logs is append-only (% rejected)', TG_OP
        USING ERRCODE = 'insufficient_privilege';
END;
$$;

CREATE TRIGGER "audit_logs_append_only"
    BEFORE UPDATE OR DELETE ON "audit_logs"
    FOR EACH ROW EXECUTE FUNCTION "audit_logs_reject_modification"();
-- TRUNCATE bypasses row triggers, so block it separately.
CREATE TRIGGER "audit_logs_no_truncate"
    BEFORE TRUNCATE ON "audit_logs"
    FOR EACH STATEMENT EXECUTE FUNCTION "audit_logs_reject_modification"();

