-- ---------- Least-privilege role for the AI service (ADR-0004) ----------
-- A NOLOGIN group role holding only the grants the AI service needs. Login users are created
-- outside migrations (docker init script locally, Terraform in AWS) so no password is ever
-- committed, and are made members of this role.

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'forge_ai') THEN
        CREATE ROLE forge_ai NOLOGIN;
    END IF;
END
$$;

GRANT USAGE ON SCHEMA public TO forge_ai;
GRANT SELECT, INSERT, UPDATE, DELETE ON "documents", "document_chunks" TO forge_ai;
GRANT INSERT ON "ai_usage" TO forge_ai;
GRANT USAGE ON SEQUENCE "document_chunks_id_seq", "ai_usage_id_seq" TO forge_ai;
